/** 연구 피험자: pseudonymous study subjects on a clinic device, each with separate records (research build only). */
import { useState } from 'preact/hooks';
import { activeSubject, addSubject, deleteSubject, listSubjects, normalizeCode, switchSubject } from '../../data/subjects';
import { AppBar, Notice } from '../components/common';
import { Icon } from '../icons';
import { fmtDate } from '../labels';

export function Subjects() {
  const [subjects, setSubjects] = useState(listSubjects);
  const [code, setCode] = useState('');
  const [msg, setMsg] = useState<string | null>(null);
  const active = activeSubject();
  const valid = normalizeCode(code);

  const add = () => {
    const s = addSubject(code);
    if (!s) {
      setMsg(valid ? '이미 있는 코드입니다.' : '영문·숫자·하이픈 2~20자로 적어 주세요(이름은 쓰지 마세요).');
      return;
    }
    switchSubject(s.code);
  };

  return (
    <>
      <AppBar title="연구 피험자" sub={active ? `지금: ${active}` : '지금: 내 기록'} onBack />
      <main class="main">
        <div class="card tight">
          <Notice>
            <span class="small">
              외래 연구용 기기에서 피험자마다 기록을 따로 저장합니다(피험자별 별도 저장소, 섞이지 않음). 이름 대신 연구 코드(예: KHU-001)만
              쓰고, 코드와 실명의 대응표는 연구 기관 문서로 따로 보관하세요. 내보내기 파일에는 이 코드가 함께 들어갑니다.
            </span>
          </Notice>
        </div>

        <div class="card">
          <h3>새 피험자</h3>
          <div class="row">
            <input
              class="grow"
              type="text"
              inputMode="text"
              autoCapitalize="characters"
              placeholder="KHU-001"
              value={code}
              aria-label="피험자 코드"
              onInput={(e) => {
                setCode((e.target as HTMLInputElement).value);
                setMsg(null);
              }}
            />
            <button class="btn primary" disabled={!valid} onClick={add}>
              추가하고 열기
            </button>
          </div>
          {msg && (
            <Notice tone="warn">
              <span class="small">{msg}</span>
            </Notice>
          )}
        </div>

        <div class="card tight">
          <div class="list">
            <button class="list-item" disabled={!active} onClick={() => switchSubject(null)}>
              <Icon name="home" />
              <div class="grow">
                내 기록 {active ? '' : '(열려 있음)'}
                <div class="xsmall muted">이 기기 주인의 기록</div>
              </div>
            </button>
            {subjects.map((s) => (
              <div class="list-item">
                <Icon name="clipboard" />
                <div class="grow">
                  {s.code} {s.code === active && <span class="chip accent">열려 있음</span>}
                  <div class="xsmall muted">{fmtDate(s.createdAt)} 추가</div>
                </div>
                {s.code !== active && (
                  <button class="btn sm" onClick={() => switchSubject(s.code)}>
                    열기
                  </button>
                )}
                <button
                  class="btn sm ghost"
                  onClick={async () => {
                    const typed = prompt(
                      `${s.code}의 기록을 이 기기에서 영구히 지웁니다. 먼저 내보내기 하세요. 지우려면 코드를 그대로 입력하세요.`,
                    );
                    if (typed?.trim().toUpperCase() !== s.code) return;
                    await deleteSubject(s.code);
                    if (s.code === active) switchSubject(null);
                    else setSubjects(listSubjects());
                  }}
                >
                  삭제
                </button>
              </div>
            ))}
          </div>
        </div>
        <p class="xsmall muted">연구용 빌드에서만 보입니다. 피험자를 바꾸면 앱이 다시 열립니다.</p>
      </main>
    </>
  );
}
